package com.MITProjectService.bot.Services.impl;import com.MITProjectCommon.common.AccountNumberGenerator;import com.MITProjectService.bot.Services.ServiceProviderService;import com.MITProjectService.bot.Services.UserPaymentAccountService;import com.MITProjectService.bot.dao.jpaRepos.UserPaymentAccountRepository;import com.MITProjectService.bot.domain.ServiceProvider;import com.MITProjectService.bot.domain.UserPaymentAccount;import com.MITProjectService.bot.enums.CommonEnums;import com.MITProjectService.bot.request.UserPaymentAccountRequest;import jakarta.annotation.Resource;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.Optional;@Servicepublic class UserPaymentAccountServiceImpl implements UserPaymentAccountService {    @Resource    private UserPaymentAccountRepository userPaymentAccountRepository;    @Resource    private ServiceProviderService serviceProviderService;    @Override    @Transactional    public UserPaymentAccount createPaymentAccount(UserPaymentAccountRequest userPaymentAccountRequest) {        Optional<ServiceProvider> user = serviceProviderService.getUserByID(userPaymentAccountRequest.getUserId());        if (user.isEmpty()) {            return null;        }        UserPaymentAccount userPaymentAccount = new UserPaymentAccount();        userPaymentAccount.setAccountBalance(BigDecimal.valueOf(0.0));        userPaymentAccount.setAccountNumber(AccountNumberGenerator.generateUniqueAccountNumber());        userPaymentAccount.setServiceProvider(user.get());        userPaymentAccount.setStatus(CommonEnums.ENABLE.getValue());        userPaymentAccount.setCurrency("LKR");        return userPaymentAccountRepository.save(userPaymentAccount);    }    @Override    public UserPaymentAccount getPaymentAccount(Long userId) {        Optional<UserPaymentAccount> userPaymentAccount = userPaymentAccountRepository.findPaymentAccountByUserId(userId);        return userPaymentAccount.orElse(null);    }}